pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        vm.assume(blockNumber % 15 == 0);
        vm.assume(timestamp > 0);
        vm.roll(blockNumber);
        vm.warp(timestamp);
        address payable caller = payable(address(new Receiver()));
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback failed");

        assertTrue(address(c).balance == 0);
    }
}

contract Receiver {
    receive() external payable {}
}
